#include <cstring>
#include <iomanip>
#include <iostream>
#include "mesh/cubed_sphere/radial_interface_jet_probe.hpp"
namespace c=cubed_sphere;constexpr int fields=9;
std::array<c::Jet,fields> Exact(const Real*x){auto X=c::Jet::Variable(x[0],0),Y=c::Jet::Variable(x[1],1),Z=c::Jet::Variable(x[2],2),R=c::Power(X*X+Y*Y+Z*Z,.5);return {c::Jet(3.14159),R,R*R,R*R*R*R*R,X+c::Jet(.2)*Y+c::Jet(.3)*Z,X*X+c::Jet(.4)*Y*Z,X*X*X+c::Jet(.2)*X*Y*Z,c::Log(c::Jet(1)+c::Jet(.1)*X+c::Jet(.2)*Y+c::Jet(.3)*Z),R*X*Y+c::Jet(.2)*Z/R};}
c::Jet MixedChart(const Real*x){auto X=c::Jet::Variable(x[0],0),Y=c::Jet::Variable(x[1],1),Z=c::Jet::Variable(x[2],2),R=c::Power(X*X+Y*Y+Z*Z,.5),U=Y/X,W=Z/X;return R*R*R*(c::Jet(1)+c::Jet(.2)*U+c::Jet(.3)*W+c::Jet(.4)*U*W+c::Jet(.2)*U*U*W*W);}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=4)throw std::runtime_error("N layers subdivision");const int n=std::stoi(argv[1]),layers=std::stoi(argv[2]),sub=std::stoi(argv[3]);auto radii=layers==1?std::vector<Real>{1}:layers==2?std::vector<Real>{.65,1}:std::vector<Real>{.45,.55,.60,.65,.70,.75,1};c::CompositeMesh mesh(.25,radii,sub,n,2);if(mesh.blocks.size()*size_t(n)*n*n>50000)throw std::runtime_error("bounded50000");c::CompositeDifference g(mesh,4,true);c::RadialInterfaceJetProbe probe(g);std::vector<Real>field(fields*g.count,0);for(size_t p=0;p<g.active.size();++p){const auto q=Exact(g.geometry[p].x);for(int f=0;f<fields;++f)field[f*g.count+g.active[p]]=q[f].f;}Real constant=0,radial_exact=0,existing_value=0,first=0,second=0,radial_owner_jet=0;Real seam_first=0,seam_second=0,angular_value=0,angular_first=0,angular_second=0;size_t angular_checks=0;size_t samples=0,owner_checks=0;bool owners_bitwise=true;std::array<Real,fields>field_first{},field_second{};
 for(size_t b=0;b<mesh.blocks.size();++b){const auto &block=mesh.blocks[b];if(block.layer!=int(radii.size())-1)continue;for(Real a:{0.,.125,.35,.5,.65,.875,1.})for(Real d:{0.,.125,.35,.5,.65,.875,1.}){Real q[3]={1,a,d},x[3];mesh.Forward(b,q,x);Real norm=0;for(Real v:x)norm+=v*v;norm=std::sqrt(norm);for(Real &v:x)v/=norm;
 for(Real radius:{.5,.7,.85,.95}){Real point[3];for(int i=0;i<3;++i)point[i]=radius*x[i];const auto truth=Exact(point);std::vector<Real>v;std::vector<std::array<Real,3>>dv;std::vector<std::array<std::array<Real,3>,3>>dd;probe.SampleJets(field,fields,point,v,dv,dd);++samples;const int owner=mesh.Owner(point);const auto old_entries=g.Interpolate(point,6);for(int f=0;f<fields;++f){Real old=0;for(const auto&e:old_entries)old+=e.weight*field[f*g.count+e.point];existing_value=std::max(existing_value,std::abs(old-v[f]));if(f==0)constant=std::max(constant,std::abs(v[f]-truth[f].f));for(int i=0;i<3;++i){const Real error=std::abs(dv[f][i]-truth[f].d[i]);field_first[f]=std::max(field_first[f],error);if(f>=4)first=std::max(first,error);if(f==0)constant=std::max(constant,std::abs(dv[f][i]));if(f>0&&f<4&&mesh.blocks[owner].face>=0)radial_exact=std::max(radial_exact,error);for(int j=0;j<3;++j){const Real e=std::abs(dd[f][i][j]-truth[f].h[i][j]);field_second[f]=std::max(field_second[f],e);if(f>=4)second=std::max(second,e);if(f==0)constant=std::max(constant,std::abs(dd[f][i][j]));if(f>0&&f<4&&mesh.blocks[owner].face>=0)radial_exact=std::max(radial_exact,e);}}}}
 for(Real radius:{.5,.7,.85,.95})if(a==0||a==1||d==0||d==1){Real point[3];for(int i=0;i<3;++i)point[i]=radius*x[i];std::vector<Real>av;std::vector<std::array<Real,3>>ad;std::vector<std::array<std::array<Real,3>,3>>ah;probe.SamplePlan(probe.Build(point,b),field,fields,av,ad,ah);for(size_t other=b+1;other<mesh.blocks.size();++other){const auto &ob=mesh.blocks[other];if(ob.layer!=int(radii.size())-1)continue;Real qother[3];mesh.Inverse(other,point,qother);const Real oriented=ob.face%2?-point[ob.face/2]:point[ob.face/2];if(!(oriented>0)||qother[1]<-1e-12||qother[1]>1+1e-12||qother[2]<-1e-12||qother[2]>1+1e-12)continue;std::vector<Real>bv;std::vector<std::array<Real,3>>bd;std::vector<std::array<std::array<Real,3>,3>>bh;probe.SamplePlan(probe.Build(point,other),field,fields,bv,bd,bh);++angular_checks;const auto truth=Exact(point);for(int f=0;f<fields;++f){angular_value=std::max(angular_value,std::abs(av[f]-bv[f]));for(int i=0;i<3;++i){angular_first=std::max(angular_first,std::abs(ad[f][i]-bd[f][i]));if(f>=4)first=std::max({first,std::abs(ad[f][i]-truth[f].d[i]),std::abs(bd[f][i]-truth[f].d[i])});for(int j=0;j<3;++j){angular_second=std::max(angular_second,std::abs(ah[f][i][j]-bh[f][i][j]));if(f>=4)second=std::max({second,std::abs(ah[f][i][j]-truth[f].h[i][j]),std::abs(bh[f][i][j]-truth[f].h[i][j])});}}}}}
 for(size_t layer=0;layer+1<radii.size();++layer){Real point[3];for(int i=0;i<3;++i)point[i]=radii[layer]*x[i];int low=-1,high=-1;for(size_t m=0;m<mesh.blocks.size();++m)if(mesh.blocks[m].face==block.face&&c::RadialInterfaceJetProbe::AngularKey(mesh.blocks[m])==c::RadialInterfaceJetProbe::AngularKey(block)){if(mesh.blocks[m].layer==int(layer))low=m;if(mesh.blocks[m].layer==int(layer)+1)high=m;}if(low<0||high<0)throw std::runtime_error("missing radial owner pair");const auto A=probe.Build(point,low),B=probe.Build(point,high);++owner_checks;std::vector<Real>sv;std::vector<std::array<Real,3>>sd;std::vector<std::array<std::array<Real,3>,3>>sh;probe.SamplePlan(A,field,fields,sv,sd,sh);const auto truth=Exact(point);for(int f=4;f<fields;++f)for(int i=0;i<3;++i){seam_first=std::max(seam_first,std::abs(sd[f][i]-truth[f].d[i]));for(int j=0;j<3;++j)seam_second=std::max(seam_second,std::abs(sh[f][i][j]-truth[f].h[i][j]));}first=std::max(first,seam_first);second=std::max(second,seam_second);if(A.terms.size()!=B.terms.size())throw std::runtime_error("radial owner plan shape");for(size_t t=0;t<A.terms.size();++t){owners_bitwise=owners_bitwise&&A.terms[t].point==B.terms[t].point&&std::memcmp(&A.terms[t].weight,&B.terms[t].weight,sizeof(c::Jet))==0;radial_owner_jet=std::max(radial_owner_jet,std::abs(A.terms[t].weight.f-B.terms[t].weight.f));for(int i=0;i<3;++i){radial_owner_jet=std::max(radial_owner_jet,std::abs(A.terms[t].weight.d[i]-B.terms[t].weight.d[i]));for(int j=0;j<3;++j)radial_owner_jet=std::max(radial_owner_jet,std::abs(A.terms[t].weight.h[i][j]-B.terms[t].weight.h[i][j]));}}}
 }}
 Real mixed_chart_error=0;std::vector<Real> mixed_field(g.count,0);for(size_t p=0;p<g.active.size();++p)if(mesh.blocks[p/(n*n*n)].face==0)mixed_field[g.active[p]]=MixedChart(g.geometry[p].x).f;for(size_t b=0;b<mesh.blocks.size();++b)if(mesh.blocks[b].face==0&&mesh.blocks[b].layer==int(radii.size())-1)for(Real a:{0.,.3,.7,1.})for(Real d:{0.,.3,.7,1.}){Real q[3]={1,a,d},x[3];mesh.Forward(b,q,x);Real norm=0;for(Real z:x)norm+=z*z;norm=std::sqrt(norm);for(Real radius:{.5,.7,.95}){Real point[3];for(int i=0;i<3;++i)point[i]=x[i]/norm*radius;std::vector<Real>v;std::vector<std::array<Real,3>>dv;std::vector<std::array<std::array<Real,3>,3>>dd;probe.SamplePlan(probe.Build(point,b),mixed_field,1,v,dv,dd);const auto exact=MixedChart(point);mixed_chart_error=std::max(mixed_chart_error,std::abs(v[0]-exact.f));for(int i=0;i<3;++i){mixed_chart_error=std::max(mixed_chart_error,std::abs(dv[0][i]-exact.d[i]));for(int j=0;j<3;++j)mixed_chart_error=std::max(mixed_chart_error,std::abs(dd[0][i][j]-exact.h[i][j]));}}}
 int rejected=0;{const Real point[3]={.1,.1,.1};std::vector<Real>v;std::vector<std::array<Real,3>>d;std::vector<std::array<std::array<Real,3>,3>>dd;try{probe.SampleJets({},1,point,v,d,dd);}catch(const std::invalid_argument&){++rejected;}}++g.mesh.revision;try{const Real point[3]={.7,.1,.1};probe.Build(point);}catch(const std::runtime_error&){++rejected;}
 std::cout<<std::setprecision(17)<<"{\"n\":"<<n<<",\"layers\":"<<layers<<",\"subdivisions\":"<<sub<<",\"cells\":"<<g.active.size()<<",\"samples\":"<<samples<<",\"constant_error\":"<<constant<<",\"radial_polynomial_jet_error\":"<<radial_exact<<",\"existing_global_value_difference\":"<<existing_value<<",\"Cartesian_MMS_first_max\":"<<first<<",\"Cartesian_MMS_second_max\":"<<second<<",\"all_radial_interface_MMS_first_max\":"<<seam_first<<",\"all_radial_interface_MMS_second_max\":"<<seam_second<<",\"angular_owner_pairs\":"<<angular_checks<<",\"angular_owner_value_jump\":"<<angular_value<<",\"angular_owner_first_jump\":"<<angular_first<<",\"angular_owner_second_jump\":"<<angular_second<<",\"radial_owner_pair_checks\":"<<owner_checks<<",\"radial_owner_all_jet_weights_bitwise\":"<<owners_bitwise<<",\"radial_owner_weight_jet_difference\":"<<radial_owner_jet<<",\"maximum_value_l1\":"<<probe.maximum_value_l1<<",\"maximum_gradient_l1_scaled\":"<<probe.maximum_gradient_l1_scaled<<",\"maximum_hessian_l1_scaled\":"<<probe.maximum_hessian_l1_scaled<<",\"maximum_radial_condition\":"<<probe.maximum_radial_condition<<",\"partition_reproduction\":"<<probe.maximum_reproduction<<",\"field_first\":[";for(int f=0;f<fields;++f){if(f)std::cout<<',';std::cout<<field_first[f];}std::cout<<"],\"field_second\":[";for(int f=0;f<fields;++f){if(f)std::cout<<',';std::cout<<field_second[f];}std::cout<<"],\"exact_mixed_radial_angular_chart_jet_error\":"<<mixed_chart_error<<",\"negative_shape_stale_controls\":"<<rejected<<",\"angular_face_contract_qualified\":false,\"no_production_adoption\":true}\n";if(constant||!owners_bitwise||mixed_chart_error>1e-8||rejected!=2||radial_exact>1e-8||existing_value>1e-10||!std::isfinite(first+second))throw std::runtime_error("radial interface jet contract failed");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
